  async convert(x: number) {

    for (let i = 1; i < this.VE.length; i++) {

      // tslint:disable-next-line: prefer-for-of
      for (let j = 1; j < this.VE[i].length; j++) {

        this.VE[i][j] = +(this.VE[i][j] / x).toFixed(0);
      }
    }
  }

  async convert2(x: number) {

    for (let i = 1; i < this.VE.length; i++) {

      // tslint:disable-next-line: prefer-for-of
      for (let j = 1; j < this.VE[i].length; j++) {

        this.VE[i][j] = +(this.VE[i][j] * x).toFixed(1);
      }
    }
  }

